typedef struct {
    const uint8_t *ptr;
    uint8_t        bit_pos;
} u8g2_dec_t;

static inline uint8_t u8g2_get_u(u8g2_dec_t *d, uint8_t cnt)
{
    uint8_t val = (uint8_t)(d->ptr[0] >> d->bit_pos);
    uint8_t next_pos = (uint8_t)(d->bit_pos + cnt);
    if (next_pos >= 8u) {
        next_pos = (uint8_t)(next_pos - 8u);
        d->ptr++;
        val |= (uint8_t)(d->ptr[0] << (cnt - next_pos));
    }
    d->bit_pos = next_pos;
    return (uint8_t)(val & ((1u << cnt) - 1u));
}

static inline int8_t u8g2_get_s(u8g2_dec_t *d, uint8_t cnt)
{
    return (int8_t)((int)u8g2_get_u(d, cnt) - (1 << (cnt - 1)));
}

static const uint8_t *u8g2_find_glyph(const uint8_t *f, uint16_t cp)
{
    const uint8_t *p = f + 23;
    if (cp <= 255u) {
        uint16_t off_A = (uint16_t)(((uint16_t)f[17] << 8) | f[18]);
        uint16_t off_a = (uint16_t)(((uint16_t)f[19] << 8) | f[20]);
        if (cp >= 'a') p += off_a;
        else if (cp >= 'A') p += off_A;
        while (p[1] != 0) {
            if (p[0] == cp) return p + 2;
            p += p[1];
        }
        return NULL;
    }

    uint16_t off_u = (uint16_t)(((uint16_t)f[21] << 8) | f[22]);
    p += off_u;
    const uint8_t *lut = p;
    uint16_t e = 0;
    do {
        p += (uint16_t)(((uint16_t)lut[0] << 8) | lut[1]);
        e  = (uint16_t)(((uint16_t)lut[2] << 8) | lut[3]);
        lut += 4;
    } while (e < cp);

    for (;;) {
        e = (uint16_t)(((uint16_t)p[0] << 8) | p[1]);
        if (e == 0) break;
        if (e == cp) return p + 3;
        p += p[2];
    }
    return NULL;
}

typedef struct {
    uint16_t cp;
    uint8_t  valid;
    int8_t   adv;
    uint16_t rows[16];
} ja16_cache_entry_t;

#define JA16_CACHE_SIZE 256u
static ja16_cache_entry_t s_ja16_cache[JA16_CACHE_SIZE];

bool font_ja16_get_glyph(uint16_t cp, uint16_t rows[16], int *out_advance)
{
    if (cp == 0) {
        memset(rows, 0, 32);
        if (out_advance) *out_advance = 8;
        return false;
    }

    uint32_t idx = ((uint32_t)cp * 2654435761u) & (JA16_CACHE_SIZE - 1u);
    ja16_cache_entry_t *ce = &s_ja16_cache[idx];
    if (ce->valid && ce->cp == cp) {
        memcpy(rows, ce->rows, 32);
        if (out_advance) *out_advance = ce->adv;
        return ce->adv > 0;
    }

    memset(rows, 0, 32);
    const uint8_t *f = s_efont_ja_16;
    const uint8_t *g = u8g2_find_glyph(f, cp);
    if (!g) {
        ce->cp = cp;
        ce->valid = 1;
        ce->adv = 0;
        memset(ce->rows, 0, 32);
        if (out_advance) *out_advance = 0;
        return false;
    }

    uint8_t b0 = f[2], b1 = f[3];
    uint8_t bw = f[4], bh = f[5], bx = f[6], by = f[7], bd = f[8];
    int8_t  max_h  = (int8_t)f[10];
    int8_t  f_yoff = (int8_t)f[12];
    int baseline = (int)max_h + (int)f_yoff; /* 16 + (-2) = 14 */

    u8g2_dec_t d = { g, 0 };
    int w    = u8g2_get_u(&d, bw);
    int h    = u8g2_get_u(&d, bh);
    int xoff = u8g2_get_s(&d, bx);
    int yoff = u8g2_get_s(&d, by);
    int xadv = u8g2_get_s(&d, bd);

    /* Center half-width non-ASCII glyphs (e.g., halfwidth katakana) inside 16x16 cell */
    int pad_x = (xadv > 0 && xadv <= 8) ? ((16 - xadv) / 2) : 0;

    if (w > 0 && h > 0) {
        int top_y = baseline - yoff - h;
        int lx = 0, ly = 0;
        while (ly < h) {
            uint8_t a = u8g2_get_u(&d, b0);
            uint8_t b = u8g2_get_u(&d, b1);
            for (;;) {
                for (uint8_t i = 0; i < a && ly < h; i++) {
                    if (++lx >= w) { lx = 0; ly++; }
                }
                for (uint8_t i = 0; i < b && ly < h; i++) {
                    int px = pad_x + xoff + lx;
                    int py = top_y + ly;
                    if (px >= 0 && px < 16 && py >= 0 && py < 16) {
                        rows[py] |= (uint16_t)(0x8000u >> px);
                    }
                    if (++lx >= w) { lx = 0; ly++; }
                }
                if (u8g2_get_u(&d, 1) == 0) break;
            }
        }
    }

    if (xadv <= 0) xadv = 16;
    ce->cp = cp;
    ce->valid = 1;
    ce->adv = (int8_t)xadv;
    memcpy(ce->rows, rows, 32);
    if (out_advance) *out_advance = xadv;
    return true;
}

#else

bool font_ja16_get_glyph(uint16_t cp, uint16_t rows[16], int *out_advance)
{
    (void)cp;
    memset(rows, 0, 32);
    if (out_advance) *out_advance = 0;
    return false;
}

#endif
